import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第五卷 答案 · 第105章 未回","description":"","frontmatter":{},"headers":[],"relativePath":"第105章_未回.md","filePath":"第105章_未回.md"}'),r={name:"第105章_未回.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第五卷-答案-·-第105章-未回" tabindex="-1">第五卷 答案 · 第105章 未回 <a class="header-anchor" href="#第五卷-答案-·-第105章-未回" aria-label="Permalink to &quot;第五卷 答案 · 第105章 未回&quot;">​</a></h1><p>后街夜市雾很重，灯晕成一团，鞋底踩在地上有点黏。</p><p>我到时周野已经占了南雾老乡小桌，顾远坐他对面，中间空一张塑料凳，凳面还留着余温。</p><p>“来得正好，刚点。”周野掰开筷子递给我，“糖水炒面，老样子。”</p><p>我坐下，棚顶灯线轻轻晃，影子落在汤碗里。老板娘端来糖水，瓷碗烫手，热气扑到脸上，红薯和姜的甜香一下暖到胃里。我双手接过来，转了半圈找个能下手的位置，又垫了张纸巾，才敢端稳。指尖被烫得发红，我捏了捏耳垂，凉意一激，才缓过来。</p><p>炒面跟着上来，铁盘滋滋响，镬气混着葱香窜起。周野挑了一大口，“还是这家火候正。”</p><p>我吃了几口才开口，“有些事没跟你们细说。”</p><p>顾远把碗推开些，“你说。”他把纸巾往我这边推了推，又把筷子摆正，像在腾出一块能好好说话的地方。</p><p>“你们都知道江苒。”我顿了顿，“我们分开一阵了。”</p><p>隔壁桌在碰杯，烤烟飘过来，我咳了一声。周野起身把棚边的帘子往下拉了拉，烟味淡了些，他才坐回去，拍拍我的背。</p><p>“我算半留守，从小跟奶奶住老街。爸妈在外做事，巷子晚上能听见远处的车声。奶奶耳朵背，我听随身听总把声音调大，磁带听了一遍又一遍，纸星星折了一罐。”</p><p>“她什么时候走近的？”顾远问。</p><p>“后街下大雾那天。”我说，“我在这小桌躲雨，她也来躲雨，看见我包侧袋的随身听，说她也有同款磁带。”</p><p>周野笑，“好老套。”</p><p>“就是老套。”我低头看碗沿的倒影，“后来就熟了，一起吃炒面喝糖水。她把纸星星分我一半，说一人一半，丢了也能凑。”</p><p>灯光晃了一下，我伸手扶住桌角，稳住那碗汤，才继续说，“平安结是奶奶教的，说结打紧了念想不散。我编了很久，红绳起毛拆了重编，指头都勒红了。我把结夹在小说稿里想送她。”</p><p>“就是你写老街那本？”周野问。</p><p>“嗯。”我说，“写雾写夜市，结尾空了名字，等她看完再填。”</p><p>顾远轻声问，“她收了？”</p><p>“退回来了。”我说，“连同写地址的纸条，说东西太重拿不动。小说压在抽屉里，没送出去。”</p><p>盘底的油凝住了，筷子挑起会拉丝。风把棚布吹鼓又压扁，灯线跟着晃，影子在碗里荡来荡去。</p><p>“什么时候的事？”周野问。</p><p>“有些日子了。”我说，“我发过信息，问稿子看不看，问结是不是编坏了，问天冷加衣没。一条又一条。”</p><p>“她回了吗？”</p><p>我摇头，喝了口转温的糖水，甜沉在碗底发腻，“石沉大海。起初屏幕一亮就拿起看，后来把手机扣过去，专心吃饭上课。可巷子一静，耳边还是磁带转到结尾咔哒一声。”</p><p>顾远忽然说了句原声，声音不高：“未回也是回，意思是让你先顾好眼前的事。”他说完看了我一眼，又补一句，“奶奶和稿子，都在眼前。”</p><p>周野给我倒热水，“那现在呢？”</p><p>“她阿婆前阵病倒了。”我说，“半夜起来头晕站不稳，医生让静养。送书的事就暂缓了。她阿婆托人带话说不急，东西在心意在。”</p><p>“好些了吗？”</p><p>“能走几步了，还会骂我炒面吃多上火。”我说，“她问爱喝糖水的姑娘怎么不来，我只说她忙。她盯着我看了半天，没再追问，只给我添了件外套。”</p><p>老板娘过来拨了拨灯线，笑着说雾大受潮，人齐就热闹。</p><p>我们都没接话。泡沫从瓶口溢出，黏在手上。我抽纸擦掉，又把瓶盖拧紧，动作慢了些，像在拖时间。</p><p>我把空碗前推，“跟奶奶住久了，我习惯等。等雾散，等倒带。等她一开始也觉得能等，可等久了忽然明白，有些未回，说到底是不想回。”</p><p>周野把焦香的面夹给我，欲言又止，又把那块最大的姜挑走，说太辣你胃不好。</p><p>“所以不再追问。”我说，“信息停在上周那条，不删也不发了。平安结收回来了，放进纸星星罐子。小说等她阿婆全好再说。”</p><p>顾远问，“算放下了？”</p><p>我没答。舌根留着糖水的甜，唇边留着炒面的咸，混在一起分不清。我用筷子尖在桌面的水渍上画了个圈，又很快抹掉。</p><p>人声渐低，有桌结账走了，凳子拖过地面刺耳响。雾更浓，灯圈外只剩电动车喇叭，飘得很远。</p><p>我摸出手机看一眼，黑屏，又扣回桌上，双手捧住热水杯。杯壁的热透过掌心传上来，我换了个姿势捧，让整只手都暖到。</p><p>“吃吧，凉了不好吃。”我拿起筷子。</p><p>三人埋头吃面，水汽凝成小滴落进碗里，晕开小圈。结账时老板娘多送一碗糖水，说煮多了，带回去给奶奶。她垫了两层纸怕烫手，我接过来紧紧抱在怀里，热气隔着纸透出来。</p><p>我拎着袋子走出夜市，雾扑到脸上，凉凉的带着余香。手机在口袋里震了一下。</p><p>我脚步顿住，手停在口袋边，没有立刻拿出来。雾落在睫毛上，我眨了眨眼，才把手拿开，继续往前走。</p>',43)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
